index 0000000..648905e
--- /dev/null
+++ b/internal/hosted/indexer/embed.go
@@ -0,0 +1,108 @@
+package indexer
+
+import (
+	"context"
+	"errors"
+	"fmt"
+	"math"
+)
+
+type EmbeddingChunk struct {
+	ID      int64
+	Content string
+}
+
+type EmbeddingProvider interface {
+	Embed(context.Context, string, []string) ([][]float32, error)
+}
+
+type StoredEmbedding struct {
+	InstallationID int64
+	RepositoryID   int64
+	ChunkID        int64
+	Model          string
+	ModelVersion   string
+	Dimensions     int
+	Vector         []float32
+}
+
+type EmbeddingStore interface {
+	UpsertEmbeddings(context.Context, []StoredEmbedding) error
+}
+
+type EmbeddingIndexer struct {
+	Provider     EmbeddingProvider
+	Store        EmbeddingStore
+	Model        string
+	ModelVersion string
+	BatchSize    int
+	MaxChunks    int
+	Dimensions   int
+}
+
+func (i EmbeddingIndexer) Index(ctx context.Context, installationID, repositoryID int64, chunks []EmbeddingChunk) error {
+	if installationID <= 0 || repositoryID <= 0 {
+		return errors.New("installation and repository IDs must be positive")
+	}
+	if i.Provider == nil || i.Store == nil || i.Model == "" || i.ModelVersion == "" {
+		return errors.New("embedding provider, store, model, and model version are required")
+	}
+	batchSize := i.BatchSize
+	if batchSize <= 0 {
+		batchSize = 64
+	}
+	maxChunks := i.MaxChunks
+	if maxChunks <= 0 {
+		maxChunks = 10_000
+	}
+	if len(chunks) > maxChunks {
+		return fmt.Errorf("embedding request has %d chunks; limit is %d", len(chunks), maxChunks)
+	}
+	for start := 0; start < len(chunks); start += batchSize {
+		end := min(start+batchSize, len(chunks))
+		inputs := make([]string, end-start)
+		for offset, chunk := range chunks[start:end] {
+			if chunk.ID <= 0 || chunk.Content == "" {
+				return fmt.Errorf("chunk at offset %d has no ID or content", start+offset)
+			}
+			inputs[offset] = chunk.Content
+		}
+		vectors, err := i.Provider.Embed(ctx, i.Model, inputs)
+		if err != nil {
+			return fmt.Errorf("embed batch starting at %d: %w", start, err)
+		}
+		if len(vectors) != len(inputs) {
+			return fmt.Errorf("embedding provider returned %d vectors for %d inputs", len(vectors), len(inputs))
+		}
+		records := make([]StoredEmbedding, len(vectors))
+		for offset, vector := range vectors {
+			if err := validateVector(vector, i.Dimensions); err != nil {
+				return fmt.Errorf("embedding for chunk %d: %w", chunks[start+offset].ID, err)
+			}
+			records[offset] = StoredEmbedding{
+				InstallationID: installationID, RepositoryID: repositoryID,
+				ChunkID: chunks[start+offset].ID, Model: i.Model, ModelVersion: i.ModelVersion,
+				Dimensions: len(vector), Vector: append([]float32(nil), vector...),
+			}
+		}
+		if err := i.Store.UpsertEmbeddings(ctx, records); err != nil {
+			return fmt.Errorf("store embedding batch starting at %d: %w", start, err)
+		}
+	}
+	return nil
+}
+
+func validateVector(vector []float32, dimensions int) error {
+	if len(vector) == 0 {
+		return errors.New("vector is empty")
+	}
+	if dimensions > 0 && len(vector) != dimensions {
+		return fmt.Errorf("vector has %d dimensions; want %d", len(vector), dimensions)
+	}
+	for _, value := range vector {
+		if math.IsNaN(float64(value)) || math.IsInf(float64(value), 0) {
+			return errors.New("vector contains a non-finite value")
+		}
+	}
+	return nil
+}

diff --git a/internal/hosted/indexer/embed_test.go b/internal/hosted/indexer/embed_test.go
new file mode 100644
index 0000000..f2d1b14
--- /dev/null
+++ b/internal/hosted/indexer/embed_test.go
@@ -0,0 +1,71 @@
+package indexer
+
+import (
+	"context"
+	"testing"
+)
+
+type embeddingStub struct {
+	batches [][]string
+}
+
+func (e *embeddingStub) Embed(_ context.Context, _ string, inputs []string) ([][]float32, error) {
+	e.batches = append(e.batches, append([]string(nil), inputs...))
+	vectors := make([][]float32, len(inputs))
+	for index := range inputs {
+		vectors[index] = []float32{float32(index), 1, 2}
+	}
+	return vectors, nil
+}
+
+type embeddingStoreStub struct{ batches [][]StoredEmbedding }
+
+func (s *embeddingStoreStub) UpsertEmbeddings(_ context.Context, records []StoredEmbedding) error {
+	copyRecords := append([]StoredEmbedding(nil), records...)
+	s.batches = append(s.batches, copyRecords)
+	return nil
+}
+
+func TestEmbeddingIndexerBatchesAndPersistsVersion(t *testing.T) {
+	provider := &embeddingStub{}
+	store := &embeddingStoreStub{}
+	indexer := EmbeddingIndexer{
+		Provider: provider, Store: store, Model: "embed-small", ModelVersion: "2026-10-01",
+		BatchSize: 2, Dimensions: 3,
+	}
+	chunks := []EmbeddingChunk{{1, "one"}, {2, "two"}, {3, "three"}, {4, "four"}, {5, "five"}}
+	if err := indexer.Index(context.Background(), 7, 9, chunks); err != nil {
+		t.Fatal(err)
+	}
+	if len(provider.batches) != 3 || len(provider.batches[0]) != 2 || len(provider.batches[2]) != 1 {
+		t.Fatalf("provider batches = %#v", provider.batches)
+	}
+	if len(store.batches) != 3 || store.batches[0][0].ModelVersion != "2026-10-01" || store.batches[0][0].InstallationID != 7 {
+		t.Fatalf("stored batches = %#v", store.batches)
+	}
+}
+
+func TestEmbeddingIndexerRejectsMalformedProviderResponse(t *testing.T) {
+	provider := malformedEmbeddingStub{}
+	indexer := EmbeddingIndexer{Provider: provider, Store: &embeddingStoreStub{}, Model: "model", ModelVersion: "v1", Dimensions: 3}
+	if err := indexer.Index(context.Background(), 1, 2, []EmbeddingChunk{{1, "one"}}); err == nil {
+		t.Fatal("expected malformed vector to fail")
+	}
+}
+
+type malformedEmbeddingStub struct{}
+
+func (malformedEmbeddingStub) Embed(context.Context, string, []string) ([][]float32, error) {
+	return [][]float32{{1, 2}}, nil
+}
+
+func TestEmbeddingIndexerCapsWorkBeforeCallingProvider(t *testing.T) {
+	provider := &embeddingStub{}
+	indexer := EmbeddingIndexer{Provider: provider, Store: &embeddingStoreStub{}, Model: "model", ModelVersion: "v1", MaxChunks: 1}
+	if err := indexer.Index(context.Background(), 1, 2, []EmbeddingChunk{{1, "one"}, {2, "two"}}); err == nil {
+		t.Fatal("expected chunk limit error")
+	}
+	if len(provider.batches) != 0 {
+		t.Fatal("provider was called before limit validation")
+	}
+}
